"""Tests for osv_check.py. No network: a fake transport answers like OSV does, and every failure path is exercised,
because a check that passes when it should fail is worse than no check."""

import datetime
import tempfile
import unittest
import urllib.error
from pathlib import Path

import osv_check
from osv_check import BAD_INPUT, CLEAN, FOUND, UNREACHABLE

TODAY = datetime.date(2026, 11, 14)
REPORT = (
    "# Aptura release runtime dependencies (generated by writeReleaseRuntimeDependencies)\n"
    "androidx.core:core:1.19.1 <- androidx.activity:activity:1.13.0\n"
    "com.google.guava:guava:33.3.1-android <- androidx.media3:media3-common:1.5.1\n"
    "org.jetbrains.kotlin:kotlin-stdlib:2.4.21 <- androidx.core:core:1.19.1\n"
)
GUAVA = "GHSA-xxph-c9ww-hj94"


class FakeOsv:
    """Answers the batch endpoint from a {package-name: [advisory ids]} map and the detail endpoint from `details`."""

    def __init__(self, advisories=None, details=None, fail=None, short_by=0):
        self.advisories = advisories or {}
        self.details = details or {}
        self.fail = fail
        self.short_by = short_by
        self.batch_calls = 0

    def post_json(self, url, body):
        if self.fail:
            raise self.fail
        self.batch_calls += 1
        results = [
            {"vulns": [{"id": i} for i in self.advisories.get(q["package"]["name"], [])]} if q["package"]["name"] in self.advisories else {}
            for q in body["queries"]
        ]
        return {"results": results[: len(results) - self.short_by]}

    def get_json(self, url):
        advisory_id = url.rsplit("/", 1)[-1]
        return self.details.get(advisory_id, {"summary": f"summary of {advisory_id}"})


def run(report=REPORT, transport=None, allowlist=None):
    with tempfile.TemporaryDirectory() as folder:
        report_file = Path(folder, "report.txt")
        report_file.write_text(report, encoding="utf-8")
        argv = [str(report_file)]
        allow_file = Path(folder, "allow.txt")
        if allowlist is not None:
            allow_file.write_text(allowlist, encoding="utf-8")
        argv += ["--allowlist", str(allow_file)]
        return osv_check.main(argv, transport or FakeOsv(), TODAY)


class ParseTests(unittest.TestCase):
    def test_header_and_blank_lines_are_skipped(self):
        self.assertEqual(
            osv_check.parse_report(REPORT),
            [("androidx.core", "core", "1.19.1"), ("com.google.guava", "guava", "33.3.1-android"),
             ("org.jetbrains.kotlin", "kotlin-stdlib", "2.4.21")],
        )

    def test_a_version_with_a_plus_is_kept_whole(self):
        found = osv_check.parse_report("com.example.media:codec-pack:1.5.0+1 <- (app)\n")
        self.assertEqual(found, [("com.example.media", "codec-pack", "1.5.0+1")])


class VerdictTests(unittest.TestCase):
    def test_a_clean_graph_passes(self):
        self.assertEqual(run(transport=FakeOsv()), CLEAN)

    def test_an_advisory_fails_and_names_the_library_and_the_id(self):
        osv = FakeOsv({"com.google.guava:guava": [GUAVA]}, {GUAVA: {"summary": "Guava deserialization DoS"}})
        code, lines = osv_check.check(osv_check.parse_report(REPORT), osv, set(), [])
        self.assertEqual(code, FOUND)
        self.assertEqual(len(lines), 1)
        self.assertIn("com.google.guava:guava:33.3.1-android", lines[0])
        self.assertIn(GUAVA, lines[0])
        self.assertEqual(run(transport=osv), FOUND)

    def test_an_allowlisted_advisory_passes_until_it_expires(self):
        osv = FakeOsv({"com.google.guava:guava": [GUAVA]})
        self.assertEqual(run(transport=osv, allowlist=f"{GUAVA}  2026-12-31  not reachable: no Java deserialization\n"), CLEAN)

    def test_an_expired_allowlist_entry_fails_again_and_says_so(self):
        osv = FakeOsv({"com.google.guava:guava": [GUAVA]})
        self.assertEqual(run(transport=osv, allowlist=f"{GUAVA}  2026-11-13  reviewed\n"), FOUND)
        code, lines = osv_check.check(osv_check.parse_report(REPORT), osv, set(), [GUAVA])
        self.assertIn("expired", lines[0])

    def test_the_day_of_expiry_still_counts_as_accepted(self):
        osv = FakeOsv({"com.google.guava:guava": [GUAVA]})
        self.assertEqual(run(transport=osv, allowlist=f"{GUAVA}  2026-11-14  last day\n"), CLEAN)

    def test_a_withdrawn_advisory_is_not_a_finding(self):
        osv = FakeOsv({"com.google.guava:guava": [GUAVA]}, {GUAVA: {"summary": "x", "withdrawn": "2026-11-01T00:00:00Z"}})
        self.assertEqual(run(transport=osv), CLEAN)

    def test_a_large_graph_is_asked_in_batches(self):
        report = "".join(f"g:a{i}:1.0 <- (app)\n" for i in range(1201))
        osv = FakeOsv()
        self.assertEqual(run(report=report, transport=osv), CLEAN)
        self.assertEqual(osv.batch_calls, 3)


class FailClosedTests(unittest.TestCase):
    def test_an_empty_report_is_rejected_not_passed(self):
        self.assertEqual(run(report="# only a header\n"), BAD_INPUT)

    def test_a_missing_report_is_rejected(self):
        self.assertEqual(osv_check.main(["/no/such/report.txt"], FakeOsv(), TODAY), BAD_INPUT)

    def test_a_malformed_allowlist_line_is_rejected_not_skipped(self):
        self.assertEqual(run(allowlist="GHSA-xxxx-xxxx-xxxx  soon  because\n"), BAD_INPUT)
        self.assertEqual(run(allowlist="GHSA-xxxx-xxxx-xxxx  2026-02-30  impossible date\n"), BAD_INPUT)
        self.assertEqual(run(allowlist="GHSA-xxxx-xxxx-xxxx\n"), BAD_INPUT)

    def test_an_unreachable_osv_is_exit_three_not_a_pass(self):
        self.assertEqual(run(transport=FakeOsv(fail=OSError("no route"))), UNREACHABLE)

    def test_a_short_answer_from_osv_is_an_error_not_a_pass(self):
        self.assertEqual(run(transport=FakeOsv(short_by=1)), UNREACHABLE)

    def test_the_real_transport_gives_up_with_an_oserror(self):
        transport = osv_check.HttpTransport(attempts=1, timeout=0.1)
        original = osv_check.urllib.request.urlopen
        osv_check.urllib.request.urlopen = lambda *a, **k: (_ for _ in ()).throw(urllib.error.URLError("down"))
        try:
            with self.assertRaises(OSError):
                transport.get_json("https://api.osv.dev/v1/vulns/x")
        finally:
            osv_check.urllib.request.urlopen = original


if __name__ == "__main__":
    unittest.main()
